/* ---------- pdf helpers ---------- */
async function pdfBytes(d){if(d.pdf.startsWith('local:')){const u=localStorage.getItem('qp_pdf_'+d.pdf.slice(6));return Uint8Array.from(atob(u),c=>c.charCodeAt(0))}return new Uint8Array(await (await fetch(d.pdf)).arrayBuffer())}
async function sha256(b){const h=await crypto.subtle.digest('SHA-256',b);return [...new Uint8Array(h)].map(x=>x.toString(16).padStart(2,'0')).join('')}
async function renderPages(el,d){el.innerHTML='<p>Loading document…</p>';const pdf=await pdfjsLib.getDocument({data:await pdfBytes(d)}).promise;el.innerHTML='';
 for(let i=0;i<pdf.numPages;i++){const p=await pdf.getPage(i+1),vp=p.getViewport({scale:1.6});const w=document.createElement('div');w.className='page';w.dataset.page=i;w.style.width=Math.min(820,vp.width/1.6*1.35)+'px';w.dataset.pw=vp.width/1.6;w.dataset.ph=vp.height/1.6;
  const c=document.createElement('canvas');c.width=vp.width;c.height=vp.height;w.appendChild(c);el.appendChild(w);await p.render({canvasContext:c.getContext('2d'),viewport:vp}).promise}d._pages=pdf.numPages}
function sigOf(d,id){return d.signers.find(s=>s.id===id)}
function visible(d,f){if(!f.cond)return true;const c=d.fields.find(x=>x.id===f.cond);return c&&c.value===true}
function calc(d,f){try{const expr=f.formula.replace(/\{([^}]+)\}/g,(_,l)=>{const r=d.fields.find(x=>x.label===l);return Number(r&&r.value)||0});if(!/^[\d\s+\-*/().]+$/.test(expr))return'ERR';return Math.round(Function('return '+expr)()*100)/100}catch(e){return'ERR'}}
async function buildSigned(d){const {PDFDocument,rgb,StandardFonts}=PDFLib;const pd=await PDFDocument.load(await pdfBytes(d));const font=await pd.embedFont(StandardFonts.Helvetica),bold=await pd.embedFont(StandardFonts.HelveticaBold);const pages=pd.getPages();
 for(const f of d.fields){if(!visible(d,f))continue;const p=pages[f.page];if(!p)continue;const {width:W,height:H}=p.getSize();const x=f.x*W,y=H-(f.y+f.h)*H,w=f.w*W,h=f.h*H;let v=f.type==='formula'?calc(d,f):f.value;if(v==null||v==='')continue;
  if(typeof v==='string'&&v.startsWith('data:image')){const img=await pd.embedPng(v);const s=Math.min(w/img.width,h/img.height);p.drawImage(img,{x,y,width:img.width*s,height:img.height*s})}
  else if(f.type==='checkbox'){if(v===true)p.drawText('X',{x:x+1,y:y+1,size:h*.9,font:bold})}
  else p.drawText(String(v),{x:x+2,y:y+h*.25,size:Math.min(11,h*.7),font,color:rgb(.07,.13,.24)})}
 const c=pd.addPage([612,792]);let y=740;const T=(t,s=10,f=font,col=rgb(.1,.1,.1))=>{c.drawText(t,{x:54,y,size:s,font:f,color:col});y-=s+8};
 T('Certificate of Completion',20,bold,rgb(.06,.46,.43));T('Easy Signatures DEMO — not a legally binding signature',9);y-=6;T('Document: '+d.name,11,bold);T('Document ID: '+d.id);T('Original SHA-256: '+(d.hashOrig||'n/a'),8);T('Completed: '+fmt(d.completed),10);y-=8;T('Recipients',12,bold);
 d.signers.forEach(s=>T(`${s.name} <${s.email||'—'}>  role: ${s.role}  ${s.done?'signed '+fmt(s.doneAt):s.role==='cc'?'copied':'pending'}  IP: 203.0.113.${(s.name.length*7)%250} (demo)`,8));y-=8;T('Audit trail',12,bold);
 d.events.forEach(e=>{if(y>50)T(`${fmt(e.ts)} — ${e.t} (${e.who})`,8)});return await pd.save()}
async function download(d){const b=await buildSigned(d);const u=URL.createObjectURL(new Blob([b],{type:'application/pdf'}));const a=document.createElement('a');a.href=u;a.download=d.name.replace(/[^\w-]+/g,'_')+'_signed.pdf';a.click();toast('Signed PDF downloaded')}
/* ---------- sortable ---------- */
function sortable(t){$$('th',t).forEach((th,i)=>th.onclick=()=>{const dir=th.classList.contains('asc')?-1:1;$$('th',t).forEach(x=>x.classList.remove('asc','desc'));th.classList.add(dir>0?'asc':'desc');const tb=t.tBodies[0];const rows=[...tb.rows];
 rows.sort((a,b)=>{let x=a.cells[i].dataset.v??a.cells[i].innerText.trim(),y=b.cells[i].dataset.v??b.cells[i].innerText.trim();const nx=parseFloat(String(x).replace(/[$,%]/g,'')),ny=parseFloat(String(y).replace(/[$,%]/g,''));if(!isNaN(nx)&&!isNaN(ny)&&/^[\d$.,%-]+$/.test(x)&&/^[\d$.,%-]+$/.test(y))return(nx-ny)*dir;return String(x).localeCompare(String(y))*dir});rows.forEach(r=>tb.appendChild(r))})}
function table(heads,rows){return `<div class="tw"><table><thead><tr>${heads.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.join('')}</tbody></table></div>`}
function afterRender(){$$('table').forEach(sortable)}
