function b64(b){let s='';for(let i=0;i<b.length;i+=8192)s+=String.fromCharCode(...b.subarray(i,i+8192));return btoa(s)}
async function imgToPdf(f,b){const {PDFDocument}=PDFLib;const pd=await PDFDocument.create();const im=f.type==='image/png'?await pd.embedPng(b):await pd.embedJpg(b);const W=612,H=792,sc=Math.min((W-72)/im.width,(H-72)/im.height,1);const pg=pd.addPage([W,H]);pg.drawImage(im,{x:(W-im.width*sc)/2,y:(H-im.height*sc)/2,width:im.width*sc,height:im.height*sc});return await pd.save()}
