 addEventListener('dragenter',e=>{if(!ok()||![...e.dataTransfer.types].includes('Files'))return;n++;ov.classList.add('on')});addEventListener('dragleave',()=>{if(--n<=0){n=0;ov.classList.remove('on')}});
