function sigModal(kind,s,cb){const saved=kind==='signature'?S.sig:S.ini;let tab=saved?'saved':'draw';
 const r=()=>{modal(`<h3>${kind==='signature'?'Adopt your signature':'Your initials'}</h3><div class="tabs">${(saved?['saved']:[]).concat(['draw','type','upload']).map(t=>`<button class="${t==tab?'on':''}" data-tb="${t}">${t[0].toUpperCase()+t.slice(1)}</button>`).join('')}</div><div id="sb"></div><br><div class="row"><button class="p" id="ad">Adopt & sign</button><button onclick="closeModal()">Cancel</button></div><p style="font-size:11px;color:var(--mut)">Demo: by adopting you agree this mark represents your signature for this document.</p>`);
  $$('[data-tb]').forEach(b=>b.onclick=()=>{tab=b.dataset.tb;r()});const sb=$('#sb');const init=s.name.split(' ').map(w=>w[0]).join('');let get;
  if(tab==='saved'){sb.innerHTML=`<img src="${saved}" style="max-width:100%;border:1px solid var(--line);border-radius:8px">`;get=()=>saved}
  if(tab==='draw'){sb.innerHTML='<canvas id="sigpad"></canvas><button id="clr" style="margin-top:6px">Clear</button>';const c=$('#sigpad');c.width=c.offsetWidth*2;c.height=340;const x=c.getContext('2d');x.lineWidth=5;x.lineCap='round';x.strokeStyle='#1e3a8a';let dn=false,any=false;
   const p=e=>{const r=c.getBoundingClientRect();return[(e.clientX-r.left)*c.width/r.width,(e.clientY-r.top)*c.height/r.height]};c.onpointerdown=e=>{dn=true;c.setPointerCapture(e.pointerId);x.beginPath();x.moveTo(...p(e))};c.onpointermove=e=>{if(dn){x.lineTo(...p(e));x.stroke();any=true}};c.onpointerup=()=>dn=false;$('#clr').onclick=()=>{x.clearRect(0,0,c.width,c.height);any=false};get=()=>any?c.toDataURL():null}
  if(tab==='type'){const fonts=['Caveat','Dancing Script','cursive'];let fi=0;sb.innerHTML=`<input id="tn" value="${esc(kind==='signature'?s.name:init)}" style="width:100%"><div id="fp">${fonts.map((f,i)=>`<div class="typed" data-fi="${i}" style="font-family:'${f}';cursor:pointer;${i==0?'background:#ecfdf5':''}">${esc(kind==='signature'?s.name:init)}</div>`).join('')}</div>`;
   const up=()=>$$('[data-fi]').forEach(e=>{e.textContent=$('#tn').value;e.style.background=e.dataset.fi==fi?'#ecfdf5':''});$('#tn').oninput=up;$$('[data-fi]').forEach(e=>e.onclick=()=>{fi=+e.dataset.fi;up()});get=()=>typedSig($('#tn').value,fonts[fi])}
  if(tab==='upload'){let u=null;sb.innerHTML='<input type="file" accept="image/png,image/jpeg" id="si"><div id="pv"></div>';$('#si').onchange=e=>{const rd=new FileReader();rd.onload=()=>{const im=new Image();im.onload=()=>{const c=document.createElement('canvas');c.width=im.width;c.height=im.height;c.getContext('2d').drawImage(im,0,0);u=c.toDataURL('image/png');$('#pv').innerHTML=`<img src="${u}" style="max-width:100%;max-height:120px">`};im.src=rd.result};rd.readAsDataURL(e.target.files[0])};get=()=>u}
  $('#ad').onclick=()=>{const u=get();if(!u)return toast('Please add a signature first');if(kind==='signature')S.sig=u;else S.ini=u;save();closeModal();cb(u)}};r()}
