   P.items.forEach(([n,q,p])=>{T(n,54,10);T(q,330,10);T($f(p),390,10);T($f(q*p),480,10);y-=18});y-=10;T('Subtotal '+$f(t.sub),400,10);y-=16;T(`Discount ${P.disc}% -${$f(t.dis)}`,400,10);y-=16;T(`Tax ${P.tax}% ${$f(t.tx)}`,400,10);y-=20;T('Total '+$f(t.total),400,13,b);
