   const by=await pd.save();let s='';for(let i=0;i<by.length;i+=8192)s+=String.fromCharCode(...by.subarray(i,i+8192));const k=uid();localStorage.setItem('qp_pdf_'+k,btoa(s));const d=blank(P.title+' — '+P.client,'local:'+k,[P.client]);
